int copy_auth_to_skb(struct xfrm_algo_auth *auth, struct sk_buff *skb) {
    struct nlattr *nla;
    size_t name_len = strlen(auth->alg_name) + 1;
    size_t key_len = auth->alg_key_len / 8;
    size_t total_len = nla_total_size(name_len) + nla_total_size(key_len);

    if (skb_tailroom(skb) < total_len) {
        return -EMSGSIZE;
    }

    nla = __nla_reserve(skb, XFRMA_ALG_AUTH, total_len);
    if (!nla) {
        return -EMSGSIZE;
    }

    nla_put(skb, XFRMA_ALG_AUTH_NAME, name_len, auth->alg_name);
    nla_put(skb, XFRMA_ALG_AUTH_KEY, key_len, auth->alg_key);

    return 0;
}
